<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
if($_SERVER['REQUEST_METHOD']==='POST'){$type=$_POST['action_type']??'';if($type==='complaint'){$borrow=one('SELECT b.*,k.id book_id FROM borrowings b JOIN books k ON k.id=b.book_id WHERE b.id=? AND b.user_id=?',[(int)($_POST['borrowing_id']??0),$user['id']]);if(!$borrow)flash('Pilih buku dari riwayat peminjaman Anda.','error');else{$photo=null;if(!empty($_FILES['evidence']['name'])&&is_uploaded_file($_FILES['evidence']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['evidence']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'],true)&&$_FILES['evidence']['size']<=5000000){$dir=__DIR__.'/../uploads/complaints';if(!is_dir($dir))mkdir($dir,0775,true);$name=bin2hex(random_bytes(12)).'.'.$ext;if(move_uploaded_file($_FILES['evidence']['tmp_name'],$dir.'/'.$name))$photo='uploads/complaints/'.$name;}}execute('INSERT INTO complaints(user_id,book_id,type,description,photo_path) VALUES(?,?,?,?,?)',[$user['id'],$borrow['book_id'],$_POST['complaint_type']??'lainnya',trim($_POST['description']??''),$photo]);flash('Aduan sudah disampaikan dan menunggu admin merespon.');redirect('member/pelaporan.php?sent=complaint');}}elseif($type==='review'){$borrow=one('SELECT book_id FROM borrowings WHERE id=? AND user_id=?',[(int)($_POST['borrowing_id']??0),$user['id']]);$rating=(int)($_POST['rating']??0);if(!$borrow||$rating<1||$rating>5||trim($_POST['review']??'')==='')flash('Lengkapi buku, rating, dan review.','error');else{execute('INSERT INTO reviews(user_id,book_id,rating,review) VALUES(?,?,?,?)',[$user['id'],$borrow['book_id'],$rating,trim($_POST['review'])]);flash('Terima kasih sudah memberikan review yang berguna.');redirect('member/pelaporan.php?sent=review');}}}
$items=rows('SELECT b.id borrowing_id,k.title,k.book_id,b.status FROM borrowings b JOIN books k ON k.id=b.book_id WHERE b.user_id=? ORDER BY b.borrowed_at DESC',[$user['id']]);member_start('Pelaporan dan Review',$user,'pelaporan.php'); ?>
<section class="member-section" id="customer-service"><span class="member-kicker">BANTU KAMI MENINGKATKAN LAYANAN</span><h1>Pelaporan &amp; Review</h1><?php if(isset($_GET['sent'])):?><div class="notice"><?=($_GET['sent']==='complaint'?'Aduan sudah disampaikan dan menunggu admin merespon.':'Terima kasih sudah direview. Review Anda berguna bagi pembaca lain.')?></div><?php endif;?><label for="report-action">Pilih tindakan</label><select id="report-action"><option value="">Pilih aduan atau review</option><option value="complaint">Buat aduan</option><option value="review">Tulis review</option></select><form class="member-form conditional-form" id="form-complaint" method="post" enctype="multipart/form-data"><input type="hidden" name="action_type" value="complaint"><label>Buku yang dipinjam<select required name="borrowing_id"><option value="">Pilih buku</option><?php foreach($items as $i):?><option value="<?=(int)$i['borrowing_id']?>"><?=e($i['title'])?> · <?=e($i['book_id'])?> (<?=e($i['status'])?>)</option><?php endforeach;?></select></label><label>Jenis aduan<select name="complaint_type"><option value="rusak">Buku rusak</option><option value="hilang">Buku hilang</option><option value="lainnya">Lainnya</option></select></label><label>Kronologi<textarea name="description" required rows="5"></textarea></label><label>Foto bukti (opsional)<input type="file" name="evidence" accept="image/jpeg,image/png,image/webp"></label><button>Kirim aduan</button></form><form class="member-form conditional-form" id="form-review" method="post"><input type="hidden" name="action_type" value="review"><label>Buku yang pernah dipinjam<select required name="borrowing_id"><option value="">Pilih buku</option><?php foreach($items as $i):?><option value="<?=(int)$i['borrowing_id']?>"><?=e($i['title'])?> · <?=e($i['book_id'])?></option><?php endforeach;?></select></label><label>Rating (1–5 bintang)<select name="rating" required><option value="">Pilih rating</option><?php for($n=1;$n<=5;$n++):?><option value="<?=$n?>"><?=$n?> ★</option><?php endfor;?></select></label><label>Review<textarea name="review" required rows="5" placeholder="Ceritakan pendapat Anda tentang buku ini"></textarea></label><button>Kirim review</button></form></section><script>document.getElementById('report-action').addEventListener('change',e=>document.querySelectorAll('.conditional-form').forEach(f=>f.classList.toggle('visible',f.id==='form-'+e.target.value)));</script><?php member_end(); ?>

